import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    strings = input_data[1:n+1]

    suffix_counts = {}

    for s in strings:
        current = ""
        for char in reversed(s):
            current = char + current
            if current in suffix_counts:
                suffix_counts[current] += 1
            else:
                suffix_counts[current] = 1

    if not suffix_counts:
        print(0)
    else:
        print(max(suffix_counts.values()))

if __name__ == "__main__":
    main()
